//! The embedded bundled default addons (spec §6), generated by
//! `build.rs` from `zim/extensions/org.zaminmc.extension.*`.
//!
//! `bundled_packages()` groups the generated rows per addon id into
//! the file-map shape the service's seeding path consumes.

use std::collections::BTreeMap;

// The generated table lives in OUT_DIR.
include!(concat!(env!("OUT_DIR"), "/bundled_addons.rs"));

/// Every bundled default addon: (manifest id, package-root-relative
/// path → bytes).
pub fn bundled_packages() -> Vec<(String, BTreeMap<String, Vec<u8>>)> {
    let mut grouped: BTreeMap<String, BTreeMap<String, Vec<u8>>> = BTreeMap::new();
    for (addon, path, bytes) in FILES {
        grouped
            .entry((*addon).to_owned())
            .or_default()
            .insert((*path).to_owned(), bytes.to_vec());
    }
    grouped.into_iter().collect()
}
